'use strict';

// 中转文本客户端：DashScope compatible-mode /v1/chat/completions（非流式）。
// 入参 messages 透传 OpenAI 结构；明文 Key 只在调用处内存，禁止落盘/日志。

const { isChatModel } = require('./catalog.cjs');
const { assertBaseUrl } = require('../endpoint-policy.cjs');

const CHAT_PATH = '/compatible-mode/v1/chat/completions';
const CHAT_MAX_BODY_BYTES = 2 * 1024 * 1024;

function chatError(code, message, status = 502) {
  const error = new Error(message);
  error.code = code;
  error.status = status;
  return error;
}

function validateMessages(messages) {
  if (!Array.isArray(messages) || messages.length === 0) {
    throw chatError('CHAT_MESSAGES_INVALID', 'messages 必须是非空数组', 400);
  }
  const allowedRoles = new Set(['system', 'user', 'assistant', 'tool', 'developer']);
  for (const m of messages) {
    if (!m || typeof m !== 'object' || Array.isArray(m)) {
      throw chatError('CHAT_MESSAGES_INVALID', 'messages 元素必须是对象', 400);
    }
    if (typeof m.role !== 'string' || !allowedRoles.has(m.role)) {
      throw chatError('CHAT_MESSAGES_INVALID', `不支持的 role：${m.role}`, 400);
    }
    const content = m.content;
    const hasContent = typeof content === 'string' ? content.length > 0
      : (Array.isArray(content) && content.length > 0);
    if (!hasContent) {
      throw chatError('CHAT_MESSAGES_INVALID', `role=${m.role} 的 content 为空`, 400);
    }
  }
  return messages;
}

function createChatClient({ fetchImpl = globalThis.fetch } = {}) {
  if (typeof fetchImpl !== 'function') throw new TypeError('fetchImpl 必须是函数');

  async function chatCompletion({ model, messages, apiKey, baseURL, temperature, maxTokens } = {}) {
    if (!isChatModel(model)) throw chatError('CHAT_MODEL_INVALID', '不支持的对话模型', 400);
    if (typeof apiKey !== 'string' || !apiKey) throw chatError('CHAT_KEY_MISSING', '缺少上游 Key', 400);
    const safeMessages = validateMessages(messages);

    const body = { model, messages: safeMessages };
    if (Number.isFinite(temperature)) body.temperature = temperature;
    if (Number.isSafeInteger(maxTokens) && maxTokens > 0) body.max_tokens = maxTokens;
    const raw = JSON.stringify(body);
    if (Buffer.byteLength(raw) > CHAT_MAX_BODY_BYTES) {
      throw chatError('CHAT_BODY_TOO_LARGE', '请求体过大', 413);
    }

    const url = assertBaseUrl(baseURL).origin + CHAT_PATH;
    const response = await fetchImpl(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${apiKey}`
      },
      body: raw
    });

    let data = null;
    try { data = await response.json(); } catch (_) { data = null; }
    if (!response.ok) {
      const status = response.status;
      const code = data?.error?.code || data?.code || '';
      if (status === 401 || status === 403 || (typeof code === 'string' && /quota|insufficient|exhausted|throttl/i.test(code))) {
        throw chatError('CHAT_KEY_UNAVAILABLE', '鉴权失败或额度不足', status);
      }
      throw chatError('CHAT_UPSTREAM_ERROR', data?.error?.message || data?.message || `上游错误 HTTP${status}`, status);
    }
    if (!data || typeof data.id !== 'string' || !Array.isArray(data.choices)) {
      throw chatError('CHAT_UPSTREAM_UNKNOWN', '上游返回结构未知');
    }
    return data;
  }

  return { chatCompletion };
}

module.exports = { createChatClient, CHAT_PATH, validateMessages };
